// Google検索結果から企業の公式ドメインを抽出し、関連度スコアで評価
const items = $input.all();
const searchResults = items[0].json.items || [];
const competitorName = $node['入力データ整理'].json.competitor_name;

const results = [];

// 検索結果がない場合のエラーハンドリング
if (searchResults.length === 0) {
  return [{
    json: {
      competitor_name: competitorName,
      domain: null,
      error: 'Google検索で結果が見つかりませんでした',
      suggestion: '企業名のスペルや表記を確認してください'
    }
  }];
}

searchResults.forEach((item, index) => {
  try {
    const url = new URL(item.link);
    const domain = url.hostname.replace('www.', '');
    const title = item.title || '';
    const snippet = item.snippet || '';

    // 関連度スコアの詳細計算
    let relevanceScore = 0;
    const lowerCompetitor = competitorName.toLowerCase();
    const lowerTitle = title.toLowerCase();
    const lowerDomain = domain.toLowerCase();
    const lowerSnippet = snippet.toLowerCase();

    // タイトルマッチング（最も重要）
    if (lowerTitle.includes(lowerCompetitor)) {
      relevanceScore += 50;
    }

    // ドメイン名マッチング
    if (lowerDomain.includes(lowerCompetitor)) {
      relevanceScore += 40;
    }

    // 説明文マッチング
    if (lowerSnippet.includes(lowerCompetitor)) {
      relevanceScore += 15;
    }

    // 公式サイトキーワード
    const officialKeywords = ['公式', 'official', 'corporate', 'company', 'corporation'];
    for (const keyword of officialKeywords) {
      if (lowerTitle.includes(keyword) || lowerSnippet.includes(keyword)) {
        relevanceScore += 25;
        break;
      }
    }

    // 検索順位ボーナス（上位ほど高い）
    relevanceScore += (6 - index) * 5;

    // 一般的でないドメイン拡張子のペナルティ
    const commonTlds = ['.com', '.co.jp', '.jp', '.org', '.net'];
    if (!commonTlds.some(tld => domain.includes(tld))) {
      relevanceScore -= 10;
    }

    results.push({
      competitor_name: competitorName,
      domain: domain,
      full_url: item.link,
      title: title,
      snippet: snippet,
      relevance_score: relevanceScore,
      search_rank: index + 1,
      is_likely_official: relevanceScore >= 60
    });
  } catch (error) {
    console.error('URL解析エラー:', error, 'URL:', item.link);
    // エラーが発生したURLもログとして記録
    results.push({
      competitor_name: competitorName,
      domain: 'parse_error',
      full_url: item.link,
      title: item.title || 'タイトル不明',
      snippet: '解析エラー',
      relevance_score: 0,
      search_rank: index + 1,
      is_likely_official: false,
      error: error.message
    });
  }
});

// 関連度スコア順にソートして上位3つを返す
const sortedResults = results.sort((a, b) => b.relevance_score - a.relevance_score);

return sortedResults.slice(0, 3).map(item => ({ json: item }));

// Google Ads Transparency Centerの検索結果を解析してAdvertiser IDを抽出
const items = $input.all();
const results = [];

items.forEach(item => {
  const htmlContent = item.json.data || item.json || '';
  const domain = item.json.domain;
  const competitorName = item.json.competitor_name;

  // Advertiser IDの抽出パターン（複数パターンに対応）
  const advertiserIdPatterns = [
    /\/advertiser\/(AR[A-Z0-9]{20,})/gi,
    /advertiser["\']?:\s*["\']?(AR[A-Z0-9]{20,})["\']?/gi,
    /data-advertiser-id["\']?:\s*["\']?(AR[A-Z0-9]{20,})["\']?/gi
  ];

  const advertiserIds = new Set(); // 重複排除のためSetを使用

  // 複数のパターンで検索
  for (const pattern of advertiserIdPatterns) {
    let match;
    while ((match = pattern.exec(htmlContent)) !== null) {
      const advertiserId = match[1];
      if (advertiserId && advertiserId.length >= 20) {
        advertiserIds.add(advertiserId);
      }
    }
  }

  // 企業名のマッチング確認
  const namePattern = new RegExp(competitorName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
  const hasCompanyName = namePattern.test(htmlContent);

  // JSONレスポンスの場合の処理
  if (typeof htmlContent === 'object' && htmlContent.ad_creatives) {
    htmlContent.ad_creatives.forEach(ad => {
      if (ad.advertiser_id && ad.advertiser_name) {
        advertiserIds.add(ad.advertiser_id);
      }
    });
  }

  // 結果処理
  if (advertiserIds.size > 0) {
    // 複数のAdvertiser IDが見つかった場合は全て処理
    Array.from(advertiserIds).forEach(advertiserId => {
      const transparencyUrl = `https://adstransparency.google.com/advertiser/${advertiserId}`;

      results.push({
        competitor_name: competitorName,
        domain: domain,
        advertiser_id: advertiserId,
        transparency_center_url: transparencyUrl,
        has_company_name_match: hasCompanyName,
        search_success: true,
        confidence_level: hasCompanyName ? 'high' : 'medium',
        extracted_from: 'html_parsing',
        timestamp: new Date().toISOString()
      });
    });
  } else {
    // 見つからない場合のフォールバック処理
    results.push({
      competitor_name: competitorName,
      domain: domain,
      advertiser_id: null,
      transparency_center_url: null,
      has_company_name_match: hasCompanyName,
      search_success: false,
      confidence_level: 'low',
      error_message: 'Google Ads Transparency Centerで広告主IDが見つかりませんでした',
      suggested_actions: [
        'ドメイン名を直接Google Ads Transparency Centerで検索',
        '企業の子会社・ブランド名で再検索',
        '英語表記での検索を試行'
      ],
      timestamp: new Date().toISOString()
    });
  }
});

return results.map(item => ({ json: item }));

// 成功時の詳細レポート生成
const data = $input.all()[0].json;

const successReport = {
  status: '✅ 発見成功',
  competitor_name: data.competitor_name,
  official_domain: data.domain,
  advertiser_id: data.advertiser_id,
  transparency_url: data.transparency_center_url,
  confidence_level: data.confidence_level,
  discovery_timestamp: data.timestamp,

  // 詳細情報
  summary: `競合企業「${data.competitor_name}」の広告透明性センターURLを発見しました。`,

  // 構造化されたレポート
  detailed_report: {
    basic_info: {
      competitor_name: data.competitor_name,
      official_domain: data.domain,
      advertiser_id: data.advertiser_id,
      confidence: data.confidence_level
    },
    urls: {
      transparency_center: data.transparency_center_url,
      direct_advertiser: `https://adstransparency.google.com/advertiser/${data.advertiser_id}`,
      search_by_domain: `https://adstransparency.google.com/search?q=${encodeURIComponent(data.domain)}`
    },
    next_steps: [
      '取得したURLにアクセスして広告データを確認',
      '広告クリエイティブのスクリーンショットを保存',
      '広告のターゲティング情報を調査',
      '広告出稿期間と頻度を分析',
      '競合他社との広告戦略を比較分析'
    ],
    analysis_points: [
      '使用されている広告コピーとメッセージング',
      'ターゲット地域とデバイス設定',
      '広告フォーマット（テキスト、画像、動画）',
      '季節性やイベントに応じた広告展開',
      '広告予算の推定と投下時期'
    ]
  },

  // マークダウン形式のレポート
  markdown_report: `# 競合広告分析結果\n\n## 基本情報\n- **競合企業名**: ${data.competitor_name}\n- **公式ドメイン**: ${data.domain}\n- **広告主ID**: ${data.advertiser_id}\n- **信頼度**: ${data.confidence_level}\n\n## 取得URL\n- **広告透明性センター**: [${data.transparency_center_url}](${data.transparency_center_url})\n\n## 次のアクション\n${data.confidence_level === 'high' ? '✅ 高信頼度でのマッチングです' : '⚠️ 念のため手動確認を推奨します'}\n\n1. 上記URLにアクセスして広告データを確認\n2. 広告クリエイティブの分析\n3. ターゲティング戦略の調査\n4. 競合分析レポートの作成`
};

return { json: successReport };

// 失敗時の詳細レポートと代替案生成
const data = $input.all()[0].json;

const failureReport = {
  status: '❌ 発見失敗',
  competitor_name: data.competitor_name,
  attempted_domain: data.domain,
  error_message: data.error_message,
  discovery_timestamp: data.timestamp,

  // 詳細情報
  summary: `競合企業「${data.competitor_name}」の広告透明性センターURLを自動発見できませんでした。`,

  // トラブルシューティングと代替案
  troubleshooting: {
    possible_reasons: [
      '企業が Google広告を出稿していない可能性',
      '検索に使用したドメインが正しくない可能性',
      '企業名の表記揺れ（英語名、日本語名、略称など）',
      'Google Ads Transparency Centerでの表示名が異なる可能性'
    ],
    alternative_actions: data.suggested_actions || [
      '手動でGoogle Ads Transparency Centerを検索',
      '企業名のバリエーション（英語・日本語）で再検索',
      '関連子会社・グループ会社名で検索',
      'ブランド名・製品名での検索'
    ]
  },

  // 手動検索のガイド
  manual_search_guide: {
    step1: 'https://adstransparency.google.com/ にアクセス',
    step2: `検索ボックスに「${data.competitor_name}」を入力`,
    step3: 'フィルターで地域・期間・広告タイプを設定',
    step4: '検索結果から該当する企業を選択',
    alternative_keywords: [
      data.competitor_name,
      data.attempted_domain,
      `${data.competitor_name} Inc`,
      `${data.competitor_name} Corp`,
      `${data.competitor_name} Company`
    ]
  },

  // 有料サービスの提案
  premium_options: {
    serpapi: {
      service: 'SerpApi Google Ads Transparency Center API',
      url: 'https://serpapi.com/google-ads-transparency-center-api',
      note: '有料ですが、より高精度な検索が可能'
    },
    alternative_tools: [
      'Facebook Ad Library (Meta)',
      'Twitter Ads Transparency Center', 
      'LinkedIn Ad Library',
      'YouTube Ad Transparency (Google)'
    ]
  },

  // マークダウン形式のレポート
  markdown_report: `# 競合広告分析結果（失敗）\n\n## 基本情報\n- **競合企業名**: ${data.competitor_name}\n- **試行ドメイン**: ${data.attempted_domain || '取得失敗'}\n- **エラー**: ${data.error_message}\n\n## 手動検索方法\n1. [Google Ads Transparency Center](https://adstransparency.google.com/) にアクセス\n2. 以下のキーワードで検索を試行:\n   ${(data.manual_search_guide?.alternative_keywords || [data.competitor_name]).map(k => `   - ${k}`).join('\n')}\n\n## 代替アプローチ\n${(data.troubleshooting?.alternative_actions || []).map((action, i) => `${i + 1}. ${action}`).join('\n')}\n\n⚠️ **注意**: この企業はGoogle広告を出稿していない可能性があります。`
};

return { json: failureReport };
